use crate::adapter::{AdapterError, AdapterRequest, AdapterResult, PlatformKind, ToolAdapter};
use crate::governance::{ExecutionPolicy, PolicyDecision};
use crate::orchestration::{AdapterId, AdapterStatus, CapabilityRequest, OrchestrationValidationError};
use crate::orchestration_audit::AuditRecord;
#[derive(Debug, Clone, PartialEq, Eq)] pub enum OrchestrationError { InvalidRequest(OrchestrationValidationError), PolicyDenied(PolicyDecision), ApprovalRequired, NoCompatibleAdapter, Adapter(AdapterError) }
pub struct Orchestrator { policy: ExecutionPolicy, adapters: Vec<Box<dyn ToolAdapter>> }
impl Orchestrator {
    pub fn new(policy: ExecutionPolicy) -> Self { Self { policy, adapters: Vec::new() } }
    pub fn register(&mut self, adapter: Box<dyn ToolAdapter>) { self.adapters.push(adapter); }
    pub fn execute(&self, request: &CapabilityRequest, platform: PlatformKind) -> Result<AdapterResult, OrchestrationError> { request.validate().map_err(OrchestrationError::InvalidRequest)?; match self.policy.evaluate(request) { PolicyDecision::Allow => {}, PolicyDecision::RequireApproval => return Err(OrchestrationError::ApprovalRequired), decision => return Err(OrchestrationError::PolicyDenied(decision)) } let adapter = self.select_adapter(request, platform, None).ok_or(OrchestrationError::NoCompatibleAdapter)?; adapter.invoke(&AdapterRequest::new(request.clone())).map_err(OrchestrationError::Adapter) }
    pub fn execute_with_audit(&self, request: &CapabilityRequest, platform: PlatformKind, audit: &mut Vec<AuditRecord>) -> Result<AdapterResult, OrchestrationError> { self.execute_with_audit_for_adapter(request, platform, None, audit).map(|(_, result)| result) }
    pub fn execute_with_audit_for_adapter(&self, request: &CapabilityRequest, platform: PlatformKind, adapter_id: Option<&AdapterId>, audit: &mut Vec<AuditRecord>) -> Result<(AdapterId, AdapterResult), OrchestrationError> { let sequence = audit.len() as u64 + 1; if let Err(error) = request.validate() { audit.push(AuditRecord::denied(sequence, request.semantic, "invalid request")); return Err(OrchestrationError::InvalidRequest(error)); } match self.policy.evaluate(request) { PolicyDecision::Allow => {}, PolicyDecision::RequireApproval => { audit.push(AuditRecord::denied(sequence, request.semantic, "approval required")); return Err(OrchestrationError::ApprovalRequired); }, decision => { audit.push(AuditRecord::denied(sequence, request.semantic, "policy denied")); return Err(OrchestrationError::PolicyDenied(decision)); } } let adapter = self.select_adapter(request, platform, adapter_id).ok_or_else(|| { audit.push(AuditRecord::denied(sequence, request.semantic, "no compatible adapter")); OrchestrationError::NoCompatibleAdapter })?; let selected_id = adapter.metadata().id().clone(); let result = adapter.invoke(&AdapterRequest::new(request.clone())); match &result { Ok(value) => audit.push(AuditRecord::invocation_finished(sequence, request.semantic, selected_id.clone(), value.success)), Err(_) => audit.push(AuditRecord::invocation_finished(sequence, request.semantic, selected_id.clone(), false)) } result.map(|value| (selected_id, value)).map_err(OrchestrationError::Adapter) }
    fn select_adapter(&self, request: &CapabilityRequest, platform: PlatformKind, requested_id: Option<&AdapterId>) -> Option<&dyn ToolAdapter> { self.adapters.iter().filter(|adapter| { let metadata = adapter.metadata(); metadata.status() >= AdapterStatus::Implemented && metadata.available_on(platform) && metadata.validate_request(request).is_ok() && requested_id.is_none_or(|id| metadata.id() == id) }).min_by(|left, right| left.metadata().id().cmp(right.metadata().id())).map(|adapter| adapter.as_ref()) }
}
#[cfg(test)] mod tests { use super::*; use crate::adapter::AdapterMetadata; use crate::capability::Capability; use crate::governance::{DenyReason, ScopeRule}; use crate::orchestration::{EffectClass, ExecutionScope, SemanticCapabilityId}; use std::sync::{atomic::{AtomicUsize, Ordering}, Arc}; struct TestAdapter { metadata: AdapterMetadata, invocations: Arc<AtomicUsize> } impl ToolAdapter for TestAdapter { fn metadata(&self) -> &AdapterMetadata { &self.metadata } fn invoke(&self, _request: &AdapterRequest) -> Result<AdapterResult, AdapterError> { self.invocations.fetch_add(1, Ordering::SeqCst); Ok(AdapterResult { success: true, output: b"ok".to_vec() }) } } fn request() -> CapabilityRequest { CapabilityRequest::new(SemanticCapabilityId::NetworkConnect, Capability::NetworkConnect, ExecutionScope::target("server.example"), EffectClass::Connect) } fn adapter(id: &str, invocations: Arc<AtomicUsize>) -> TestAdapter { TestAdapter { metadata: AdapterMetadata::new(AdapterId::new(id), AdapterStatus::Implemented, vec![Capability::NetworkConnect], vec![PlatformKind::Linux]), invocations } }
#[test] fn denied_request_never_reaches_adapter_invocation() { let invocations = Arc::new(AtomicUsize::new(0)); let mut orchestrator = Orchestrator::new(ExecutionPolicy::default()); orchestrator.register(Box::new(adapter("network.native", Arc::clone(&invocations)))); assert_eq!(orchestrator.execute(&request(), PlatformKind::Linux), Err(OrchestrationError::PolicyDenied(PolicyDecision::Deny(DenyReason::MissingCapability)))); assert_eq!(invocations.load(Ordering::SeqCst), 0); }
#[test] fn approved_request_selects_compatible_adapter_and_invokes_once() { let invocations = Arc::new(AtomicUsize::new(0)); let policy = ExecutionPolicy::default().grant(Capability::NetworkConnect).allow_scope(Capability::NetworkConnect, ScopeRule::Target("server.example".into())); let mut orchestrator = Orchestrator::new(policy); orchestrator.register(Box::new(adapter("network.native", Arc::clone(&invocations)))); let result = orchestrator.execute(&request(), PlatformKind::Linux).expect("request should execute"); assert!(result.success); assert_eq!(result.output, b"ok"); assert_eq!(invocations.load(Ordering::SeqCst), 1); }
#[test] fn materially_incompatible_adapter_is_rejected_before_invocation() { let invocations = Arc::new(AtomicUsize::new(0)); let policy = ExecutionPolicy::default().grant(Capability::NetworkConnect).allow_scope(Capability::NetworkConnect, ScopeRule::Target("server.example".into())); let mut orchestrator = Orchestrator::new(policy); orchestrator.register(Box::new(TestAdapter { metadata: AdapterMetadata::new(AdapterId::new("network.admin-only"), AdapterStatus::Implemented, vec![Capability::NetworkAdmin], vec![PlatformKind::Linux]), invocations: Arc::clone(&invocations) })); assert_eq!(orchestrator.execute(&request(), PlatformKind::Linux), Err(OrchestrationError::NoCompatibleAdapter)); assert_eq!(invocations.load(Ordering::SeqCst), 0); }
#[test] fn requested_adapter_identity_is_resolved_deterministically() { let invocations = Arc::new(AtomicUsize::new(0)); let policy = ExecutionPolicy::default().grant(Capability::NetworkConnect).allow_scope(Capability::NetworkConnect, ScopeRule::Target("server.example".into())); let mut orchestrator = Orchestrator::new(policy); orchestrator.register(Box::new(adapter("network.native", Arc::clone(&invocations)))); let mut audit = Vec::new(); let (id, result) = orchestrator.execute_with_audit_for_adapter(&request(), PlatformKind::Linux, Some(&AdapterId::new("network.native")), &mut audit).expect("named adapter should execute"); assert_eq!(id.as_str(), "network.native"); assert!(result.success); assert_eq!(invocations.load(Ordering::SeqCst), 1); }
}